                froms.get(Sheet.gradeTermsKey(grade))));
        if (latePct != null) {
            setLatePct(user, sheetId, latePct, froms.get(Sheet.LATE_PCT));
        }
        if (policyDate != null) {
            setPolicyDate(user, sheetId, policyDate.orElse(null));
