        for (Claim claim : chosen) {
            try {
                changed.add(transaction.execute(status -> changeStatus(user, sheetId, claim.getId(), next)));
            } catch (ResponseStatusException refused) {
                // Left as it is: its transaction rolled back, writing nothing.
            }
        }
